function pointerPos(ev){let r=canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)*W/r.width,y:(ev.clientY-r.top)*H/r.height}}
function cellAt(x,y){let col=Math.floor((x-OX)/TW),row=Math.floor((y-OY)/TH);return col>=0&&col<COLS&&row>=0&&row<ROWS?{x:col,y:row}:null}
canvas.addEventListener('pointermove',ev=>{let p=pointerPos(ev),c=cellAt(p.x,p.y);game.hover=c?{kind:'tile',...c}:null});canvas.addEventListener('pointerleave',()=>game.hover=null);
canvas.addEventListener('pointerdown',ev=>{ev.preventDefault();let p=pointerPos(ev),c=cellAt(p.x,p.y);if(!c)return;if(game.phase==='day'){let crop=plotAt(c.x,c.y);if(crop&&crop.ready){let val=seedData[crop.type].value;game.gold+=val;game.harvests++;let {x,y}=tile(c.x,c.y);game.floaters.push({x:x+34,y:y+23,text:`+${val}g`,color:'#ffef9a',life:1.4});game.plots.splice(game.plots.indexOf(crop),1);journal(`${crop.type==='berry'?'Moonberry':'Turnip'} harvested · +${val}g`);updateUI();return}if(plotCells.some(t=>t.x===c.x&&t.y===c.y)&&!crop){if(!game.seeds[game.seed]){journal('No seeds left. Buy some in the satchel.');return}game.seeds[game.seed]--;game.plots.push({x:c.x,y:c.y,type:game.seed,stage:0,ready:false});journal(`${game.seed==='berry'?'Moonberry':'Turnip'} planted`);updateUI()}else if(crop&&!crop.ready){journal('Still growing — let it see another moonrise.')}}else{if(isPath(c.x,c.y)||plotAt(c.x,c.y)||towerAt(c.x,c.y)){journal('That spot is already in use. Try open grass.');return}let spec=towerData[game.tower];if(game.gold<spec.cost){journal('Not enough gold for that defense.');return}game.gold-=spec.cost;game.towers.push({x:c.x,y:c.y,type:game.tower,cool:0});let {x,y}=tile(c.x,c.y);game.particles.push(...Array.from({length:9},(_,i)=>({x:x+34,y:y+30,vx:Math.cos(i)*20,vy:Math.sin(i)*20,color:'#f5d378',life:.8})));journal(`${game.tower==='pea'?'Peashooter':'Glow lantern'} placed`);updateUI()}});
document.querySelectorAll('.seed-row').forEach(el=>el.onclick=()=>{game.seed=el.dataset.seed;updateUI()});document.querySelectorAll('.tower-card').forEach(el=>el.onclick=()=>{game.tower=el.dataset.tower;updateUI()});
document.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>{let kind=el.dataset.buy,cost=kind==='turnip'?12:15;if(game.gold<cost){journal('Not enough gold for those seeds.');return}game.gold-=cost;game.seeds[kind]+=kind==='turnip'?3:1;journal(kind==='turnip'?'Bought 3 turnip seeds':'Bought a moonberry seed');updateUI()});
function startNight(){game.phase='night';game.spawned=0;game.total=5+Math.floor((game.day-1)*1.65);game.nightDuration=6+game.total*1.35;game.nightTimer=0;game.spawnClock=.5;game.ended=false;journal(`Sundown · ${game.total} critters stirring`);updateUI()}
document.getElementById('phaseButton').onclick=startNight;document.getElementById('startButton').onclick=()=>document.getElementById('introModal').classList.add('hidden');
function spawnEnemy(){let p=path[0],pos=tile(p.x,p.y),r=Math.random(),type=game.day>=3&&r<.2?'brute':game.day>=2&&r<.48?'swift':'normal',hp=type==='brute'?22+game.day*2:type==='swift'?8+game.day:12+game.day*1.3,speed=type==='brute'?26:type==='swift'?51:36;game.enemies.push({x:pos.x+TW/2,y:pos.y+TH/2,hp,maxHp:hp,speed,type,pathIndex:0,progress:0});game.spawned++}
function explode(x,y,color){for(let i=0;i<8;i++){let a=Math.PI*2*i/8;game.particles.push({x,y,vx:Math.cos(a)*(18+Math.random()*22),vy:Math.sin(a)*(18+Math.random()*22),color,life:.55+Math.random()*.3})}}
let last=performance.now();function loop(now){let dt=Math.min(.04,(now-last)/1000);last=now;if(game.phase==='night'&&!game.ended)updateNight(dt);updateEffects(dt);drawFarm();requestAnimationFrame(loop)}
function updateNight(dt){game.nightTimer+=dt;game.spawnClock-=dt;let interval=Math.max(.48,1.22-game.day*.045);if(game.spawned<game.total&&game.spawnClock<=0){spawnEnemy();game.spawnClock=interval}
// enemies follow winding trail
for(let i=game.enemies.length-1;i>=0;i--){let e=game.enemies[i],distance=e.speed*dt;while(distance>0&&e.pathIndex<path.length-1){let next=path[e.pathIndex+1],pos=tile(next.x,next.y),tx=pos.x+TW/2,ty=pos.y+TH/2,dx=tx-e.x,dy=ty-e.y,d=Math.hypot(dx,dy),step=Math.min(d,distance);e.x+=dx/d*step;e.y+=dy/d*step;distance-=step;if(step>=d-.01)e.pathIndex++}if(e.pathIndex>=path.length-1){game.enemies.splice(i,1);game.hp=Math.max(0,game.hp-(e.type==='brute'?2:1));game.shake=5;journal('A night critter reached the cottage!');updateUI();if(game.hp<=0){finishNight(false);return}}}
// towers target furthest-progress enemy in range
for(let t of game.towers){t.cool-=dt;if(t.cool>0)continue;let spec=towerData[t.type],pos=tile(t.x,t.y),cx=pos.x+TW/2,cy=pos.y+TH/2,target=null,far=-1;for(let e of game.enemies){let d=Math.hypot(e.x-cx,e.y-cy),progress=e.pathIndex*100+e.progress;if(d<=spec.range&&progress>far){far=progress;target=e}}if(target){t.cool=spec.rate;let dx=target.x-cx,dy=target.y-cy,d=Math.hypot(dx,dy);game.shots.push({x:cx,y:cy,vx:dx/d*(t.type==='pea'?310:240),vy:dy/d*(t.type==='pea'?310:240),target,damage:spec.damage,color:spec.color,radius:t.type==='pea'?4:6})}}
for(let i=game.shots.length-1;i>=0;i--){let s=game.shots[i];if(!game.enemies.includes(s.target)){game.shots.splice(i,1);continue}let dx=s.target.x-s.x,dy=s.target.y-s.y,d=Math.hypot(dx,dy),step=(Math.hypot(s.vx,s.vy)*dt);if(d<=step+6){s.target.hp-=s.damage;explode(s.target.x,s.target.y,s.color);if(s.target.hp<=0){let idx=game.enemies.indexOf(s.target);if(idx>=0){game.gold+=2;game.enemies.splice(idx,1);game.floaters.push({x:s.target.x,y:s.target.y-10,text:'+2g',color:'#f4dc80',life:1});updateUI()}}game.shots.splice(i,1)}else{s.x+=s.vx*dt;s.y+=s.vy*dt}}
if(game.spawned>=game.total&&game.enemies.length===0){finishNight(true)}}
function finishNight(won){game.ended=true;game.phase='day';game.shots=[];if(won){game.gold+=8;game.hp=Math.min(game.maxHp,game.hp+1);for(let p of game.plots){if(p.ready)continue;p.stage++;if(p.stage>=seedData[p.type].grow)p.ready=true}document.getElementById('endIcon').textContent='🌤️';document.getElementById('endTitle').textContent='The hollow is safe!';document.getElementById('endText').textContent=`Night ${game.day} is behind you. You earned 8g for keeping watch, and the garden grew beneath the stars. Crops are ready when they glow. Your cottage mended a little, too.`;journal(`Dawn · survived wave ${game.day} · +8g`)}else{document.getElementById('endIcon').textContent='🕯️';document.getElementById('endTitle').textContent='The lights went out…';document.getElementById('endText').textContent='The critters reached your cottage. Your hollow needs a fresh start. Your planted garden remains, but the night is growing bolder.';document.getElementById('continueButton').textContent='Try again from dawn →';journal('The cottage fell quiet. Try another night.')}
document.getElementById('continueButton').onclick=()=>{document.getElementById('endModal').classList.add('hidden');if(!won){game.hp=game.maxHp;game.gold=Math.max(game.gold,24);game.enemies=[];game.towers=[];game.day=1;game.plots=[];game.seeds={turnip:5,berry:2};game.harvests=0;journal('A new spring morning · the hollow is yours again')}else game.day++;game.ended=false;updateUI()};document.getElementById('endModal').classList.remove('hidden');updateUI()}
function updateEffects(dt){for(let i=game.particles.length-1;i>=0;i--){let p=game.particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.life<=0)game.particles.splice(i,1)}for(let i=game.floaters.length-1;i>=0;i--){let f=game.floaters[i];f.y-=24*dt;f.life-=dt;if(f.life<=0)game.floaters.splice(i,1)}if(game.shake>0)game.shake=Math.max(0,game.shake-dt*20)}
updateUI();journal('Spring morning · the garden is yours');requestAnimationFrame(loop);
</script></body></html>

