const c=document.getElementById('game'),g=c.getContext('2d'),W=960,H=570,C=12,R=7,TW=68,TH=60,OX=66,OY=62;const seeds={turnip:{grow:1,value:16},berry:{grow:2,value:34}},types={pea:{cost:24,range:155,damage:3,rate:.76,color:'#a8d776'},lantern:{cost:38,range:120,damage:7,rate:1.25,color:'#ffd16e'}};const beds=[];for(let y=1;y<=4;y++)for(let x=1;x<=3;x++)beds.push({x,y});const path=[{x:0,y:5},{x:1,y:5},{x:2,y:5},{x:3,y:5},{x:4,y:5},{x:4,y:4},{x:4,y:3},{x:5,y:3},{x:6,y:3},{x:7,y:3},{x:7,y:4},{x:7,y:5},{x:8,y:5},{x:9,y:5},{x:10,y:5},{x:10,y:4},{x:10,y:3},{x:10,y:2},{x:11,y:2}];const S={day:1,gold:30,hp:8,harvest:0,phase:'day',seed:'turnip',tower:'pea',bag:{turnip:5,berry:2},plots:[],towers:[],enemies:[],shots:[],particles:[],floaters:[],spawned:0,total:0,clock:0,hover:null,over:false,log:[]};const xy=(x,y)=>({x:OX+x*TW,y:OY+y*TH}),onPath=(x,y)=>path.some(p=>p.x===x&&p.y===y),plot=(x,y)=>S.plots.find(p=>p.x===x&&p.y===y),tower=(x,y)=>S.towers.find(p=>p.x===x&&p.y===y);function say(s){S.log.unshift(s);S.log=S.log.slice(0,4);document.getElementById('journal').innerHTML=S.log.map((a,i)=>`<div>${i?'·':'✦'} ${a}</div>`).join('')}function ui(){document.getElementById('day').textContent=S.day+' · Spring';document.getElementById('gold').textContent=S.gold+'g';document.getElementById('harvests').textContent=S.harvest;document.getElementById('hp').textContent=S.hp+' / 8';document.getElementById('turnipCount').textContent='× '+S.bag.turnip;document.getElementById('berryCount').textContent='× '+S.bag.berry;document.getElementById('wave').textContent='WAVE '+S.day;document.getElementById('phase').textContent=S.phase==='day'?'Daytime · tending':'Moonrise · wave '+S.day;document.getElementById('scene').classList.toggle('night',S.phase==='night');document.getElementById('help').innerHTML=S.phase==='day'?'<b>Day:</b> choose seeds, tap a soil bed to plant, harvest ripe crops.':'<b>Night:</b> select a defense, tap open grass. Protect the cottage!';let b=document.getElementById('phaseBtn');b.disabled=S.phase==='night'||S.over;b.className='action'+(S.phase==='night'?' nightbtn':'');b.textContent=S.phase==='day'?'🌙  End day & face the night':'🌙  Night watch in progress';document.getElementById('hint').textContent=S.phase==='day'?'Plant and harvest now. Crops grow one stage when you survive the night.':'Place defenses and watch the meadow. Towers fire automatically.';document.querySelectorAll('[data-seed]').forEach(e=>e.classList.toggle('sel',e.dataset.seed===S.seed));document.querySelectorAll('[data-tower]').forEach(e=>e.classList.toggle('sel',e.dataset.tower===S.tower))}function cell(x,y){let a=Math.floor((x-OX)/TW),b=Math.floor((y-OY)/TH);return a>=0&&a<C&&b>=0&&b<R?{x:a,y:b}:null}function pos(e){let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)*W/r.width,y:(e.clientY-r.top)*H/r.height}}c.onpointermove=e=>{let p=pos(e),q=cell(p.x,p.y);S.hover=q?{kind:'tile',...q}:null};c.onpointerleave=()=>S.hover=null;c.onpointerdown=e=>{e.preventDefault();let p=pos(e),q=cell(p.x,p.y);if(!q)return;if(S.phase==='day'){let z=plot(q.x,q.y);if(z&&z.ready){let v=seeds[z.type].value;S.gold+=v;S.harvest++;S.floaters.push({x:xy(q.x,q.y).x+34,y:xy(q.x,q.y).y+25,text:'+'+v+'g',color:'#ffef9a',life:1.4});S.plots.splice(S.plots.indexOf(z),1);say((z.type==='berry'?'Moonberry':'Turnip')+' harvested · +'+v+'g');ui();return}if(beds.some(a=>a.x===q.x&&a.y===q.y)&&!z){if(!S.bag[S.seed])return say('No seeds left. Buy some in the satchel.');S.bag[S.seed]--;S.plots.push({x:q.x,y:q.y,type:S.seed,stage:0,ready:false});say(S.seed+' planted');ui()}else if(z)say('Still growing — let it see another moonrise.')}else{if(onPath(q.x,q.y)||plot(q.x,q.y)||tower(q.x,q.y))return say('That spot is already in use. Try open grass.');let d=types[S.tower];if(S.gold<d.cost)return say('Not enough gold for that defense.');S.gold-=d.cost;S.towers.push({x:q.x,y:q.y,type:S.tower,cool:0});say(S.tower==='pea'?'Peashooter placed':'Glow lantern placed');ui()}};document.querySelectorAll('[data-seed]').forEach(e=>e.onclick=()=>{S.seed=e.dataset.seed;ui()});document.querySelectorAll('[data-tower]').forEach(e=>e.onclick=()=>{S.tower=e.dataset.tower;ui()});document.querySelectorAll('[data-buy]').forEach(e=>e.onclick=()=>{let k=e.dataset.buy,v=k==='turnip'?12:15;if(S.gold<v)return say('Not enough gold for those seeds.');S.gold-=v;S.bag[k]+=k==='turnip'?3:1;say(k==='turnip'?'Bought 3 turnip seeds':'Bought a moonberry seed');ui()});document.getElementById('start').onclick=()=>document.getElementById('intro').classList.add('hidden');document.getElementById('phaseBtn').onclick=()=>{S.phase='night';S.spawned=0;S.total=5+(S.day-1)*2;S.clock=.5;S.over=false;say('Sundown · '+S.total+' critters stirring');ui()};function spawn(){let p=path[0],a=xy(p.x,p.y),r=Math.random(),type=S.day>=3&&r<.2?'brute':S.day>=2&&r<.48?'swift':'normal',hp=type==='brute'?22+S.day*2:type==='swift'?8+S.day:12+S.day*1.3;S.enemies.push({x:a.x+TW/2,y:a.y+TH/2,hp,max:hp,speed:type==='brute'?26:type==='swift'?51:36,type,i:0});S.spawned++}function pop(x,y,color){for(let i=0;i<7;i++){let a=Math.PI*2*i/7;S.particles.push({x,y,vx:Math.cos(a)*(20+Math.random()*18),vy:Math.sin(a)*(20+Math.random()*18),color,life:.6})}}function endNight(ok){S.over=true;S.phase='day';S.shots=[];if(ok){S.gold+=8;S.hp=Math.min(8,S.hp+1);for(let p of S.plots){if(p.ready)continue;if(++p.stage>=seeds[p.type].grow)p.ready=true}document.getElementById('endIcon').textContent='🌤️';document.getElementById('endTitle').textContent='The hollow is safe!';document.getElementById('endText').textContent='Night '+S.day+' is behind you. You earned 8g, and the garden grew beneath the stars. Crops glow when ready. Your cottage mended a little, too.';document.getElementById('continue').textContent='Welcome the morning →';say('Dawn · survived wave '+S.day+' · +8g')}else{document.getElementById('endIcon').textContent='🕯️';document.getElementById('endTitle').textContent='The lights went out…';document.getElementById('endText').textContent='Critters reached your