function rect(x,y,w,h,r){g.beginPath();g.roundRect(x,y,w,h,r)}function tile(x,y,night){let a=xy(x,y),p=onPath(x,y);g.fillStyle=p?(night?'#554e47':'#b59e79'):(night?'#335540':`rgb(${78+(x*7+y*13)%8},${126+(x*5+y*9)%9},${84+(x*3+y*7)%7})`);g.fillRect(a.x,a.y,TW,TH);if(p){g.fillStyle=night?'#625950':'#c3aa82';g.fillRect(a.x+2,a.y+3,TW-4,TH-6);for(let n=0;n<3;n++){g.fillStyle=night?'#766b5e':'#d0b991';g.beginPath();g.ellipse(a.x+10+(x*31+n*19+y*13)%48,a.y+13+(y*17+n*11+x*3)%35,2.4,1.3,-.4,0,7);g.fill()}}else if((x*3+y*5)%4===0){g.fillStyle=night?'#506f4e':'#729366';g.beginPath();g.ellipse(a.x+15+(x*19%41),a.y+15+(y*7%25),2,1.1,.5,0,7);g.fill()}g.strokeStyle=night?'#203e35':'#416f4d';g.lineWidth=1;g.strokeRect(a.x+.5,a.y+.5,TW-1,TH-1)}
